function documentTitle(doc:Doc){
 if(doc.display_title?.trim())return doc.display_title.trim();
 const title=doc.title.trim();
 const generic=/^(?:powerpoint presentation|microsoft powerpoint(?:\s*[-:].*)?|microsoft word(?: document)?|presentation|untitled(?: document)?|document|\(anonymous\))$/i;
 return !title||generic.test(title)?doc.filename.replace(/\.[^.]+$/,'').replace(/_+/g,' ').replace(/\s+/g,' ').trim():title;
}

