function Dialog({title,onClose,children,wide=false}:{title:string;onClose:()=>void;children:ReactNode;wide?:boolean}){
 const box=useRef<HTMLDivElement>(null);
 useEffect(()=>{const old=document.activeElement as HTMLElement;(box.current?.querySelector<HTMLElement>('input:not([type=hidden]),select,textarea')||box.current?.querySelector<HTMLElement>('button'))?.focus();return()=>old?.focus();},[]);
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><div className={wide?"dialog wide-dialog":"dialog"} ref={box} role="dialog" aria-modal="true" aria-label={title} onKeyDown={e=>{if(e.key==='Tab'){const all=box.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]');if(!all?.length)return;const first=all[0],last=all[all.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}}><div className="dialog-heading"><div className="dialog-symbol"><Folder size={21}/></div><button className="icon-button" aria-label="Close dialog" onClick={onClose}><X size={19}/></button></div><h2>{title}</h2>{children}</div></div>;
}
function FolderForm({existing,onSave}:{existing?:FolderData;onSave:(name:string,color:string)=>Promise<void>}){
 const [name,setName]=useState(existing?.name||''),[color,setColor]=useState(existing?.color||colors[0]),[saving,setSaving]=useState(false);
 return <form onSubmit={async e=>{e.preventDefault();setSaving(true);await onSave(name,color);setSaving(false);}}><p className="dialog-copy">Bring related documents together. You can always change this later.</p><label className="field-label">Folder name<input required maxLength={128} placeholder="e.g. Theory of Computation" value={name} onChange={e=>setName(e.target.value)}/></label><label className="field-label">Folder color</label><div className="color-options">{colors.map(c=><button type="button" key={c} aria-label={`Choose color ${c}`} aria-pressed={color.toLowerCase()===c.toLowerCase()} style={{background:c}} onClick={()=>setColor(c)}>{color.toLowerCase()===c.toLowerCase()&&<Check size={16}/>}</button>)}</div><div className="dialog-actions"><button className="button primary" disabled={!name.trim()||saving}>{saving?<LoaderCircle size={15} className="spin"/>:<Plus size={15}/>} {existing?'Save changes':'Create folder'}</button></div></form>;
}

function Viewer({data,onClose,onRecover,api,onReadingPage,onReadingError}:{onReadingPage:(page:number)=>Promise<void>;onReadingError:(message:string)=>void;data:ViewerData;onClose:()=>void;onRecover:()=>void;api:(path:string,method?:string,body?:unknown)=>Promise<Response>}){
 const frame=useRef<HTMLDivElement>(null);
 useEffect(()=>{const old=document.activeElement as HTMLElement;frame.current?.querySelector<HTMLButtonElement>('button')?.focus();return()=>old?.focus();},[]);
 const [pdfPages,setPdfPages]=useState(data.doc.page_count),[page,setPage]=useState(data.page),[zoom,setZoom]=useState(1),[error,setError]=useState(''),[query,setQuery]=useState(''),[hits,setHits]=useState<Hit[]>([]),[searching,setSearching]=useState(false),[note,setNote]=useState(''),[boxes,setBoxes]=useState<number[][]>([]);
 const reader=useRef<ContinuousPdfHandle>(null);
 const latestPage=useRef(data.page),persistPage=useRef(onReadingPage),reportReadingError=useRef(onReadingError);
 latestPage.current=page;persistPage.current=onReadingPage;reportReadingError.current=onReadingError;
 useEffect(()=>{latestPage.current=page;const timer=setTimeout(()=>{void persistPage.current(latestPage.current).catch(e=>reportReadingError.current((e as Error).message));},700);return()=>clearTimeout(timer);},[page]);
 useEffect(()=>{function flush(){void persistPage.current(latestPage.current).catch(e=>reportReadingError.current((e as Error).message));}function hidden(){if(document.visibilityState==='hidden')flush();}document.addEventListener('visibilitychange',hidden);window.addEventListener('pagehide',flush);return()=>{document.removeEventListener('visibilitychange',hidden);window.removeEventListener('pagehide',flush);flush();};},[]);
 function goToPage(number:number){setPage(number);reader.current?.goToPage(number);}
 useEffect(()=>{let alive=true;setBoxes([]);if(!data.hit)return;if(data.hit.amount_match?.highlight_box&&data.hit.source_sha256===data.doc.sha256){setBoxes([data.hit.amount_match.highlight_box]);return;}const literal=data.hit.amount_match?.evidence||data.hit.passage.slice(0,500);void api(`/documents/${data.doc.id}/highlight?page=${data.hit.page_number}&text=${encodeURIComponent(literal)}`).then(r=>r.json()).then(r=>{if(alive)setBoxes(r.boxes);}).catch(()=>{});return()=>{alive=false;};},[data.doc.id,data.hit]);
 async function searchDocument(e:FormEvent){e.preventDefault();if(!query.trim())return;setSearching(true);try{const result=await(await api('/search','POST',{query,document_id:data.doc.id,content_only:true})).json() as SearchResult;setHits(result.results);setNote(result.response?result.response.text:result.results.length?'Matching pages in this file':'No strong source match in this document.');}catch(e){setNote((e as Error).message);}finally{setSearching(false);}}
 return <div ref={frame} className="viewer-backdrop" onKeyDown={e=>{if(e.key!=='Tab')return;const all=frame.current?.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],input,select');if(!all?.length)return;const first=all[0],last=all[all.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}} role="dialog" aria-modal="true" aria-label={`Document viewer: ${data.doc.filename}`}><header className="viewer-header"><button className="button secondary small" onClick={onClose}><ArrowLeft size={14}/>Back</button><span className="pdf-mini"><FileText size={18}/></span><div><strong>{data.doc.title}</strong><small>{data.doc.folder_name}<span>·</span>{data.doc.filename}</small></div><a className="button secondary small" target="_blank" rel="noreferrer" href={`/api/documents/${data.doc.id}/file#page=${page}`}>{isAndroid()?(data.doc.filename.toLowerCase().endsWith('.pdf')?'Original':'Preview PDF'):(data.doc.filename.toLowerCase().endsWith('.pdf')?'Original PDF':'Slide PDF')}<ArrowUpRight size={14}/></a>{!data.doc.filename.toLowerCase().endsWith('.pdf')&&<a className="button secondary small" href={'/api/documents/'+data.doc.id+'/original'}>{isAndroid()?'PowerPoint':'Download PowerPoint'}</a>}<button className="icon-button" aria-label="Close document viewer" onClick={onClose}><X size={21}/></button></header><div className="viewer-layout"><div className="pdf-column"><div className="pdf-toolbar"><div className="page-controls"><button className="icon-button" aria-label="Previous page" disabled={page<=1} onClick={()=>goToPage(page-1)}><ChevronLeft size={18}/></button><label>Page <input type="number" min={1} max={pdfPages} aria-label="PDF page number" value={page} onChange={e=>{const n=Number(e.target.value);if(Number.isInteger(n)&&n>=1&&n<=(pdfPages))goToPage(n);}}/> of {pdfPages}</label><button className="icon-button" aria-label="Next page" disabled={page>=(pdfPages)} onClick={()=>goToPage(page+1)}><ChevronRight size={18}/></button></div><select aria-label="PDF zoom" value={zoom} onChange={e=>setZoom(Number(e.target.value))}><option value={.75}>75%</option><option value={1}>Fit width</option><option value={1.25}>125%</option><option value={1.5}>150%</option></select><span className="pdf-page-kind">Continuous scroll</span></div>{error?<div className="pdf-reader-shell"><div className="pdf-error" role="alert"><AlertCircle size={23}/><p>The PDF page could not open. Its original may be unavailable or changed.</p><button className="button primary" onClick={onRecover}>Fix source or extraction</button><details><summary>Technical details</summary><p>{error}</p></details><a href={`/api/documents/${data.doc.id}/file#page=${page}`} target="_blank" rel="noreferrer">Open the source PDF</a></div></div>:<ContinuousPdf ref={reader} id={data.doc.id} initialPage={data.page} zoom={zoom} boxes={boxes} highlightPage={data.hit?.page_number} onPageChange={setPage} onReady={setPdfPages} onError={setError}/>}</div><aside className="viewer-context"><div className="viewer-aside-heading"><Search size={16}/><h2>Explore this document</h2></div><form className="document-search" onSubmit={e=>void searchDocument(e)}><input aria-label="Search this document" placeholder="Ask about this document…" value={query} onChange={e=>setQuery(e.target.value)}/><button className="icon-button" aria-label="Run document search" disabled={searching||!query.trim()}>{searching?<LoaderCircle className="spin" size={16}/>:<ArrowUpRight size={17}/>}</button></form>{note&&<p className="viewer-note">{note}</p>}{hits.map(h=><button className="viewer-hit" key={h.chunk_id} onClick={()=>goToPage(h.page_number)}><strong>PDF page {h.page_number}<ArrowUpRight size={12}/></strong><span>{h.passage.slice(0,210)}</span></button>)}{data.hit&&<div className="matched-context"><h3>Matching text</h3><button className="page-tag" onClick={()=>goToPage(data.hit!.page_number)}>PDF page {data.hit.page_number}<ArrowUpRight size={13}/></button><p>{data.hit.passage}</p><small>Exact indexed source text{data.hit.extraction_method==='ocr'?' · OCR requires review':''}</small></div>}{!isAndroid()&&<PaperReference key={data.doc.id} id={data.doc.id} api={api}/>}<PageTables api={api} id={data.doc.id} page={page}/><details className="source-details"><summary>File details</summary><dl><dt>File</dt><dd>{data.doc.filename}</dd><dt>Collection</dt><dd>{data.doc.folder_name}</dd><dt>Pages</dt><dd>{data.doc.page_count}</dd><dt>Size</dt><dd>{prettyBytes(data.doc.size_bytes)}</dd><dt>Index status</dt><dd>{status(data.doc.status)}</dd></dl><p><ShieldCheck size={13}/>Opened from the matching file on this device.</p></details></aside></div></div>;
}
